def parcel_revision_report(events):
    latest={}
    for row in events:
        old=latest.get(row['id'])
        if old is None or row['revision']>old['revision']:
            latest[row['id']]=row
    totals={};canceled=[]
    for id,row in latest.items():
        if row['canceled']:
            canceled.append(id)
        else:
            point=row['point'].strip()
            totals[point]=totals.get(point,0)+row['qty']
    return {'totals':dict(sorted(totals.items())),'canceled':sorted(canceled)}

