def apply_stock_batch(initial,commands):
    result=dict(initial)
    for index,(op,sku,qty) in enumerate(commands):
        if op not in ('put','take') or sku not in result or type(qty) is not int or qty<0:
            return {'ok':False,'stock':dict(initial),'failed':index}
        if op=='take' and result[sku]<qty:
            return {'ok':False,'stock':dict(initial),'failed':index}
        result[sku]+=qty if op=='put' else -qty
    return {'ok':True,'stock':result,'failed':None}

