import csv,re
from io import StringIO
def time_log_report(text):
    rows=csv.reader(StringIO(text),delimiter=';')
    header=next(rows,None)
    if header is None:return {'minutes':{},'rejected':[]}
    if header!=['person','minutes']:raise ValueError('Неверный заголовок')
    totals={};rejected=[]
    for index,row in enumerate(rows,1):
        if len(row)!=2 or not row[0].strip() or re.fullmatch(r'[0-9]+',row[1].strip()) is None:
            rejected.append(index);continue
        person=row[0].strip();minutes=int(row[1].strip())
        totals[person]=totals.get(person,0)+minutes
    return {'minutes':dict(sorted(totals.items())),'rejected':rejected}

import json,hashlib,re
def check_file_manifest(text,files):
    items=json.loads(text)
    if type(items) is not list:raise ValueError('Нужен список')
    seen=set();verified=[];missing=[];mismatched=[]
    for item in items:
        if type(item) is not dict or set(item)!={'name','size','sha256'}:raise ValueError('Неверные поля')
        name=item['name'];size=item['size'];sha=item['sha256']
        if type(name) is not str or name in ('','.', '..') or '/' in name or chr(92) in name or name in seen:
            raise ValueError('Неверное имя')
        if type(size) is not int or size<0 or type(sha) is not str or re.fullmatch(r'[0-9a-f]{64}',sha) is None:
            raise ValueError('Неверное описание')
        seen.add(name)
        if name not in files:missing.append(name)
        elif len(files[name])!=size or hashlib.sha256(files[name]).hexdigest()!=sha:mismatched.append(name)
        else:verified.append(name)
    return {'verified':sorted(verified),'missing':sorted(missing),'mismatched':sorted(mismatched),'extra':sorted(set(files)-seen)}

